public int findMinimumWeightWalk(int N, int M, int[][] edges) {
    if (N <= 0 || M < 0 || edges == null || edges.length != M) {
        return -1;
    }

    // Initialize adjacency matrix for Floyd-Warshall algorithm
    int[][] dist = new int[N][N];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (i == j) {
                dist[i][j] = 0;
            } else {
                dist[i][j] = Integer.MAX_VALUE / 2; // Use a large number to represent infinity
            }
        }
    }

    // Fill the adjacency matrix with given edges
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        int w = edge[2];
        dist[u][v] = Math.min(dist[u][v], w);
    }

    // Floyd-Warshall algorithm to find shortest paths between all pairs of vertices
    for (int k = 0; k < N; k++) {
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (dist[i][k] < Integer.MAX_VALUE / 2 && dist[k][j] < Integer.MAX_VALUE / 2) {
                    dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);
                }
            }
        }
    }

    // Check if there is a walk that visits all vertices
    int minWeight = Integer.MAX_VALUE;
    for (int i = 0; i < N; i++) {
        int totalWeight = 0;
        boolean valid = true;
        for (int j = 0; j < N; j++) {
            if (dist[i][j] == Integer.MAX_VALUE / 2) {
                valid = false;
                break;
            }
            totalWeight += dist[i][j];
        }
        if (valid) {
            minWeight = Math.min(minWeight, totalWeight);
        }
    }

    return minWeight == Integer.MAX_VALUE ? -1 : minWeight;
}
